const fs = require('fs');

const templatePath = '/home/node/.n8n-files/SQTR.md';
const sqtrTemplate = fs.readFileSync(templatePath, 'utf8');

if (!sqtrTemplate || !sqtrTemplate.trim()) {
  throw new Error('SQTR.md template is missing or empty.');
}

const items = $input.all();

if (!items.length) {
  throw new Error('No STC items received for SQTR generation.');
}

const blocks = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const md = (item.json?.data || item.json?.text || item.json?.markdown || '').trim();

  if (!md) continue;

  const sourceFileName =
    item.json?._trace?.sourceFileName || `stc_${i + 1}.md`;

  const stcId =
    item.json?._meta?.stcId ||
    (md.match(/\|\s*\*\*STC ID\*\*\s*\|\s*([^|]+)\|/i)?.[1] || '').trim();

  blocks.push([
    `### STC_EVIDENCE_${i + 1}`,
    `SOURCE_FILE: ${sourceFileName}`,
    stcId ? `STC_ID: ${stcId}` : '',
    md
  ].filter(Boolean).join('\n'));
}

if (!blocks.length) {
  throw new Error('No valid STC markdown content found to build SQTR input.');
}

return [
  {
    json: {
      sqtrTemplate,
      stcEvidenceBlocks: blocks.join('\n\n---\n\n'),
      stcCount: blocks.length,
      _meta: {
        reportType: 'sqtr',
        outputName: `SQTR-${new Date().toISOString().slice(0, 10)}`
      },
      _trace: {
        sourceFileName: 'SQTR.md',
        uploadIndex: 0
      }
    }
  }
];

const item = $input.item;
const out = item.json.output || item.json.text || '';

if (!out.includes('# SOFTWARE QUALITY TEST REPORT') || !out.includes('| Field | Value |')) {
  throw new Error('AI did not return full SQTR markdown; refusing to continue.');
}

const lines = out.split(/\r?\n/);
let inTable = false;
let rowCount = 0;

for (const line of lines) {
  if (/^\|\s*Test Case ID\s*\|/i.test(line)) {
    inTable = true;
    continue;
  }

  if (!inTable) continue;

  if (!line.trim().startsWith('|')) break;
  if (/^\|\s*-+/.test(line)) continue;

  const cells = line.split('|').map((c) => c.trim()).slice(1, -1);
  if (cells.length >= 4) {
    const hasAnyValue = cells.some((c) => c);
    if (hasAnyValue) rowCount++;
  }
}

const expected = Number(item.json.stcCount || 0);

if (expected && rowCount !== expected) {
  throw new Error(`SQTR row mismatch: expected ${expected} STC rows but AI returned ${rowCount}.`);
}

item.json.data = out;
return item;

