const item = $input.item;
const md = String(item.json?.data ?? item.json?.text ?? item.json?.markdown ?? '').trim();

if (!md) {
  throw new Error('Bug markdown is empty before ClickUp mapping.');
}

function extract(patterns) {
  for (const pattern of patterns) {
    const m = md.match(pattern);
    if (m && m[1] != null) return String(m[1]).trim();
  }
  return '';
}

const stcId = extract([
  /\|\s*\*\*STC ID\*\*\s*\|\s*([^|]+)\|/i,
  /\|\s*\*\*Linked STC ID\*\*\s*\|\s*([^|]+)\|/i,
  /\bSTC[-\w/]+\b/i
]);

const title = extract([
  /\|\s*\*\*Title\*\*\s*\|\s*([^|]+)\|/i,
  /\|\s*\*\*Bug Title\*\*\s*\|\s*([^|]+)\|/i,
  /\|\s*\*\*Summary\*\*\s*\|\s*([^|]+)\|/i
]);

const endpointUrl = extract([
  /\|\s*\*\*(?:Endpoint URL|Endpoint|URL)\*\*\s*\|\s*([^|]+)\|/i
]);

const expectedResult = extract([
  /\|\s*\*\*Expected Result\*\*\s*\|\s*([\s\S]*?)\|(?:\r?\n|$)/i
]);

const actualResult = extract([
  /\|\s*\*\*Actual Result\*\*\s*\|\s*([\s\S]*?)\|(?:\r?\n|$)/i
]);

const requestBody = extract([
  /\|\s*\*\*Request Body\*\*\s*\|\s*([\s\S]*?)\|(?:\r?\n|$)/i,
  /\|\s*\*\*Payload\*\*\s*\|\s*([\s\S]*?)\|(?:\r?\n|$)/i
]);

const fallbackTitle =
  title ||
  extract([/\|\s*\*\*ID Number#?\*\*\s*\|\s*([^|]+)\|/i]) ||
  'Untitled bug';

const taskName = [stcId, fallbackTitle].filter(Boolean).join(' - ').slice(0, 255);

let bugSummary = '';
if (expectedResult || actualResult) {
  bugSummary = `Expected: ${expectedResult || 'Not provided'}\nActual: ${actualResult || 'Not provided'}`;
} else {
  bugSummary = 'Expected vs actual result was not fully available in the parsed bug markdown.';
}

item.json.clickup = {
  stcId,
  title: fallbackTitle,
  taskName,
  bugSummary,
  endpointUrl,
  expectedResult,
  actualResult,
  requestBody,
  description: [
    'Bug Summary',
    bugSummary,
    '',
    stcId ? `STC ID: ${stcId}` : '',
    endpointUrl ? `Endpoint URL: ${endpointUrl}` : '',
    expectedResult ? `Expected Result:\n${expectedResult}` : '',
    actualResult ? `Actual Result:\n${actualResult}` : '',
    requestBody ? `Request Body:\n${requestBody}` : ''
  ].filter(Boolean).join('\n')
};

return item;

const item = $input.item;
item.json.clickupTaskStatus = 'skipped';
item.json.clickupTaskMessage = 'ClickUp task was skipped because one or more required fields were missing.';
return item;

const item = $input.item;
const taskId = item.json?.id || item.json?.task?.id || item.json?.data?.id || '';
const hasError = !!(item.json?.error || item.json?.message && !taskId);

item.json.clickupTaskStatus = hasError ? 'failed' : 'created';
item.json.clickupTaskId = taskId || '';
item.json.clickupTaskMessage = hasError
  ? String(item.json.error?.message || item.json.message || 'ClickUp task creation failed.')
  : 'ClickUp task created successfully.';
return item;

